Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PREFMUNICIPIO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &PrefMunicipio1.FromString(&GridStateDynamicFilter.Value) If not &PrefMunicipio1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterPrefMunicipioDescription = format('%1 (%2)', "Municipio", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterPrefMunicipioDescription = format('%1 (%2)', "Municipio", "WWP_FilterContains") EndCase &PrefMunicipio = &PrefMunicipio1 print printBlockFilterPrefMunicipio EndIf Case &DynamicFiltersSelector1 = !'PREFNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefNome1.FromString(&GridStateDynamicFilter.Value) If not &prefNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprefNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterprefNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &prefNome = &prefNome1 print printBlockFilterprefNome EndIf Case &DynamicFiltersSelector1 = !'PREFCNPJ' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefCNPJ1.FromString(&GridStateDynamicFilter.Value) If not &prefCNPJ1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprefCNPJDescription = format('%1 (%2)', "CNPJ", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterprefCNPJDescription = format('%1 (%2)', "CNPJ", "WWP_FilterContains") EndCase &prefCNPJ = &prefCNPJ1 print printBlockFilterprefCNPJ EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PREFMUNICIPIO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &PrefMunicipio2.FromString(&GridStateDynamicFilter.Value) If not &PrefMunicipio2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterPrefMunicipioDescription = format('%1 (%2)', "Municipio", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterPrefMunicipioDescription = format('%1 (%2)', "Municipio", "WWP_FilterContains") EndCase &PrefMunicipio = &PrefMunicipio2 print printBlockFilterPrefMunicipio EndIf Case &DynamicFiltersSelector2 = !'PREFNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefNome2.FromString(&GridStateDynamicFilter.Value) If not &prefNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprefNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterprefNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &prefNome = &prefNome2 print printBlockFilterprefNome EndIf Case &DynamicFiltersSelector2 = !'PREFCNPJ' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefCNPJ2.FromString(&GridStateDynamicFilter.Value) If not &prefCNPJ2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprefCNPJDescription = format('%1 (%2)', "CNPJ", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterprefCNPJDescription = format('%1 (%2)', "CNPJ", "WWP_FilterContains") EndCase &prefCNPJ = &prefCNPJ2 print printBlockFilterprefCNPJ EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PREFMUNICIPIO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &PrefMunicipio3.FromString(&GridStateDynamicFilter.Value) If not &PrefMunicipio3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterPrefMunicipioDescription = format('%1 (%2)', "Municipio", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterPrefMunicipioDescription = format('%1 (%2)', "Municipio", "WWP_FilterContains") EndCase &PrefMunicipio = &PrefMunicipio3 print printBlockFilterPrefMunicipio EndIf Case &DynamicFiltersSelector3 = !'PREFNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefNome3.FromString(&GridStateDynamicFilter.Value) If not &prefNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprefNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterprefNomeDescription = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &prefNome = &prefNome3 print printBlockFilterprefNome EndIf Case &DynamicFiltersSelector3 = !'PREFCNPJ' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefCNPJ3.FromString(&GridStateDynamicFilter.Value) If not &prefCNPJ3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprefCNPJDescription = format('%1 (%2)', "CNPJ", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterprefCNPJDescription = format('%1 (%2)', "CNPJ", "WWP_FilterContains") EndCase &prefCNPJ = &prefCNPJ3 print printBlockFilterprefCNPJ EndIf EndCase EndIf EndIf EndIf If not (&TFprefCodigo.IsEmpty() AND &TFprefCodigo_To.IsEmpty()) print printBlockTFprefCodigo &TFprefCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFprefCodigo_To EndIf If not &TFprefNome_Sel.IsEmpty() print printBlockTFprefNome_Sel Else If not &TFprefNome.IsEmpty() print printBlockTFprefNome EndIf EndIf If not &TFprefCNPJ_Sel.IsEmpty() print printBlockTFprefCNPJ_Sel Else If not &TFprefCNPJ.IsEmpty() print printBlockTFprefCNPJ EndIf EndIf If not &TFPrefMunicipio_Sel.IsEmpty() print printBlockTFPrefMunicipio_Sel Else If not &TFPrefMunicipio.IsEmpty() print printBlockTFPrefMunicipio EndIf EndIf If not &TFprefEstado_Sel.IsEmpty() print printBlockTFprefEstado_Sel Else If not &TFprefEstado.IsEmpty() print printBlockTFprefEstado EndIf EndIf If not &TFprefTelefone_Sel.IsEmpty() print printBlockTFprefTelefone_Sel Else If not &TFprefTelefone.IsEmpty() print printBlockTFprefTelefone EndIf EndIf If not &TFprefContato_Sel.IsEmpty() print printBlockTFprefContato_Sel Else If not &TFprefContato.IsEmpty() print printBlockTFprefContato EndIf EndIf &TFprefStatus_Sels.FromJson(&TFprefStatus_SelsJson) If not &TFprefStatus_Sels.Count = 0 &i = 1 For &TFprefStatus_Sel in &TFprefStatus_Sels If &i = 1 &TFprefStatus_SelDscs = '' Else &TFprefStatus_SelDscs += ', ' EndIf &FilterTFprefStatus_SelValueDescription = '' Do Case Case &TFprefStatus_Sel.ToString().Trim() = !"A" &FilterTFprefStatus_SelValueDescription = "Ativo"
Case &TFprefStatus_Sel.ToString().Trim() = !"I" &FilterTFprefStatus_SelValueDescription = "Inativo"
EndCase
&TFprefStatus_SelDscs += &FilterTFprefStatus_SelValueDescription &i += 1 EndFor print printBlockTFprefStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsprefeituras order prefCodigo when &OrderedBy = 1 AND &OrderedDsc = False order (prefCodigo) when &OrderedBy = 1 AND &OrderedDsc = True order prefNome when &OrderedBy = 2 AND &OrderedDsc = False order (prefNome) when &OrderedBy = 2 AND &OrderedDsc = True order prefCNPJ when &OrderedBy = 3 AND &OrderedDsc = False order (prefCNPJ) when &OrderedBy = 3 AND &OrderedDsc = True order PrefMunicipio when &OrderedBy = 4 AND &OrderedDsc = False order (PrefMunicipio) when &OrderedBy = 4 AND &OrderedDsc = True order prefEstado when &OrderedBy = 5 AND &OrderedDsc = False order (prefEstado) when &OrderedBy = 5 AND &OrderedDsc = True order prefTelefone when &OrderedBy = 6 AND &OrderedDsc = False order (prefTelefone) when &OrderedBy = 6 AND &OrderedDsc = True order prefContato when &OrderedBy = 7 AND &OrderedDsc = False order (prefContato) when &OrderedBy = 7 AND &OrderedDsc = True order prefStatus when &OrderedBy = 8 AND &OrderedDsc = False order (prefStatus) when &OrderedBy = 8 AND &OrderedDsc = True
using trnsprefeiturasWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &PrefMunicipio1, &prefNome1, &prefCNPJ1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &PrefMunicipio2, &prefNome2, &prefCNPJ2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &PrefMunicipio3, &prefNome3, &prefCNPJ3, &TFprefCodigo , &TFprefCodigo_To, &TFprefNome, &TFprefNome_Sel, &TFprefCNPJ, &TFprefCNPJ_Sel, &TFPrefMunicipio , &TFPrefMunicipio_Sel, &TFprefEstado, &TFprefEstado_Sel, &TFprefTelefone, &TFprefTelefone_Sel, &TFprefContato , &TFprefContato_Sel, &TFprefStatus_Sels) &prefStatusDescription = '' Do Case Case prefStatus.ToString().Trim() = !"A" &prefStatusDescription = "Ativo"
Case prefStatus.ToString().Trim() = !"I" &prefStatusDescription = "Inativo"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsprefeiturasWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsprefeiturasWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsprefeiturasWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPREFCODIGO" &TFprefCodigo.FromString(&GridStateFilterValue.Value) &TFprefCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPREFNOME" &TFprefNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFNOME_SEL" &TFprefNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCNPJ" &TFprefCNPJ.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCNPJ_SEL" &TFprefCNPJ_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFMUNICIPIO" &TFPrefMunicipio.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFMUNICIPIO_SEL" &TFPrefMunicipio_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFESTADO" &TFprefEstado.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFESTADO_SEL" &TFprefEstado_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFTELEFONE" &TFprefTelefone.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFTELEFONE_SEL" &TFprefTelefone_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCONTATO" &TFprefContato.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFCONTATO_SEL" &TFprefContato_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPREFSTATUS_SEL" &TFprefStatus_SelsJson = &GridStateFilterValue.Value &TFprefStatus_Sels.FromJson(&TFprefStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
